import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # load PTX module via the provided harness API
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # ensure fp16 tensors
        Q = Q.to(torch.float16)
        K = K.to(torch.float16)
        V = V.to(torch.float16)

        out = torch.empty_like(Q, dtype=torch.float16)

        B = Q.shape[0]
        H = Q.shape[1]
        S = Q.shape[2]
        D = Q.shape[3]

        # launch configuration: grid = (seq_len, heads, batch), block = (embed_dim,1,1)
        grid = (S, H, B)
        block = (D, 1, 1)

        args = [
            Q.data_ptr(),
            K.data_ptr(),
            V.data_ptr(),
            out.data_ptr(),
            int(B),
            int(H),
            int(S),
            int(D)
        ]

        ptx_launch(self.module, "sdpa_naive", grid, block, args)
        return out
